/// Finalizes the receipt of the unstaked tokens for a submitted batch once its
/// unbonding waiting period has completed.
///
/// This instructs the staker contract to send the unstaked native tokens back to
/// this contract via [`StakerExecuteMsg::ReceiveUnstakedTokens`].
pub fn receive_batch(
    deps: DepsMut,
    env: Env,
    info: MessageInfo,
    batch_id: BatchId,
) -> ContractResult<Response> {
    nonpayable(&info)?;
    ensure_not_stopped(deps.as_ref())?;

    let SubmittedBatch {
        receive_time,
        expected_native_unstaked,
        ..
    } = deps
        .storage
        .maybe_read::<SubmittedBatches>(&batch_id)?
        .ok_or(ContractError::BatchNotFound { batch_id })?;

    ensure!(
        env.block.time.seconds() > receive_time,
        ContractError::BatchNotReady {
            now: env.block.time.seconds(),
            ready_at: receive_time,
        }
    );

    Ok(Response::new()
        // instruct the staker to send the unstaked native tokens back to this contract
        .add_message(wasm_execute(
            deps.storage.read_item::<StakerAddress>()?.to_string(),
            &StakerExecuteMsg::ReceiveUnstakedTokens { batch_id },
            vec![],
        )?)
        .add_event(ReceiveBatch {
            batch_id,
            amount: expected_native_unstaked,
        }))
}

