    let balance = deps
        .querier
        .query_balance(&env.contract.address, &native_token_denom)?;

    Ok(Response::new().add_message(wasm_execute(
        deps.storage.read_item::<LstHub>()?,
        &lst::msg::ExecuteMsg::ReceiveUnstakedTokens { batch_id },
        vec![balance],
    )?))
